// <auto-generated> by cs/tools/ts2cs.mjs from src/sim/relationships.ts, then fixed by hand where it says so.
// Relationships: what survivors think of each other, -100..100.
//
// Time spent close together (within NEAR tiles, both awake) warms them to
// each other, a little every BOND_EVERY ticks. A breakdown sours things: the
// survivor lashes out at whoever is nearest, and if that one already
// disliked them enough, it comes to blows. A friend's death hurts far more
// than a stranger's (mood.ts).
#nullable disable warnings
namespace LoonieRoo.Sim;

public static partial class Relationships
{

    public const int BOND_EVERY = 200;

    public const int BOND = 2;

    public const int NEAR = 3;

    public const int FRIEND = 30;

    public const double RIVAL = -30;

    /// <summary>A survivor this disliked by the one they lash out at gets hit back.</summary>
    public const double FIGHT_BELOW = -40;

    public const int LASH_OUT = 25;

    public const int FIGHT_DAMAGE = 60;

    public static double opinion(Survivor of, Survivor about)
    {
        return Js.Q(of.opinions[Js.Idx(about.id)], 0);
    }

    public static void adjust(Survivor of, Survivor about, int by)
    {
        of.opinions[Js.Idx(about.id)] = JsMath.max(-100, JsMath.min(100, opinion(of, about) + by));
    }
    public static void adjust(Survivor of, Survivor about, double by) => adjust(of, about, (int)by);

    /// <summary>Every BOND_EVERY ticks: survivors near each other, both awake, warm to each other.</summary>
    public static void updateRelationships(SimState state)
    {
        if ((state.tick % BOND_EVERY) != 0)
        {
            return;
        }
        var awake = state.survivors.filter((s) => !Js.T(Js.T(s.sleep?.asleep)));
        for (var i = 0; i < awake.length; i++)
        {
            for (var j = i + 1; j < awake.length; j++)
            {
                var a = Js.NN(awake[Js.Idx(i)]);
                var b = Js.NN(awake[Js.Idx(j)]);
                if (Space.manhattan(a.pos, b.pos) > NEAR)
                {
                    continue;
                }
                adjust(a, b, BOND);
                adjust(b, a, BOND);
            }
        }
    }

    /// <summary>A breakdown begins: lash out at the nearest awake survivor; a rival hits back.</summary>
    public static void lashOut(SimState state, Survivor s)
    {
        var target = state.survivors.filter((o) => ((o != s) && !Js.T(Js.T(o.sleep?.asleep))) && (Space.manhattan(o.pos, s.pos) <= 5)).sort((a, b) => Space.manhattan(a.pos, s.pos) - Space.manhattan(b.pos, s.pos))[Js.Idx(0)];
        if (!Js.T(target))
        {
            return;
        }
        var fight = opinion(target, s) <= FIGHT_BELOW;
        adjust(s, target, -LASH_OUT);
        adjust(target, s, -LASH_OUT);
        if (!Js.T(fight))
        {
            Events.logEvent(state, $"{Js.Str(s.name)} lashed out at {Js.Str(target.name)}");
            return;
        }
        foreach (var who in Js.Iter((List<double>)[s, target]))
        {
            who.health = JsMath.max(1, who.health - FIGHT_DAMAGE);
            who.lastHurtBy = "a fight";
            who.hurtTick = state.tick;
        }
        Events.logEvent(state, $"{Js.Str(s.name)} and {Js.Str(target.name)} came to blows");
    }

    /// <summary>Someone died: forget them. Returns the ids of those who counted them a friend.</summary>
    public static JsSet<string> forget(SimState state, Survivor dead)
    {
        var friends = new JsSet<string>();
        foreach (var s in Js.Iter(Expeditions.everyone(state)))
        {
            if (opinion(s, dead) >= FRIEND)
            {
                friends.add(s.id);
            }
            s.opinions.Remove(Js.Str(dead.id));
        }
        return friends;
    }

    /// <summary>"friends: Bea; rivals: Cal" for panels.</summary>
    public static string describeRelations(SimState state, Survivor s)
    {
        /*TODO return type*/object names(Func<double, bool> pick)
        {
            return state.survivors.filter((o) => (o != s) && Js.T(pick(opinion(s, o)))).map((o) => o.name);
        }
        var friends = names((v) => v >= FRIEND);
        var rivals = names((v) => v <= RIVAL);
        return new[] { Js.T(friends.length) ? $"friends: {Js.Str(friends.join(", "))}" : "", Js.T(rivals.length) ? $"rivals: {Js.Str(rivals.join(", "))}" : "" }.ToList().filter(Boolean).join("; ");
    }
}
